package ug.audiocity.studio;
import java.util.*;
public class VocalTests {
 static int passed;static void check(boolean c,String message){if(!c)throw new AssertionError(message);passed++;}
 static float[] voice(double hz,double cents,double vibrato,int frames){float[] a=new float[frames*2];double phase=0;for(int i=0;i<frames;i++){double t=i/(double)Core.RATE,f=hz*Math.pow(2,(cents+vibrato*Math.sin(2*Math.PI*4.5*t))/1200);phase+=2*Math.PI*f/Core.RATE;double env=Math.min(1,i/960.0)*Math.min(1,(frames-1-i)/960.0);float x=(float)((Math.sin(phase)+.6*Math.sin(phase*2)+.35*Math.sin(phase*3)+.22*Math.sin(phase*5))*.12*env);a[i*2]=x;a[i*2+1]=x*.6f;}return a;}
 static float[] correct(float[] source,PitchCorrector.Config c)throws Exception{float[] result=new float[source.length];int[] n={0};PitchCorrector.correct(new Core.Memory(source),c,(l,r)->{result[n[0]++]=l;result[n[0]++]=r;});check(n[0]==result.length,"Tuning keeps exact clip duration");return result;}
 // Independent full-rate normalized autocorrelation estimator, constrained around a known test note.
 static double frequency(float[] a,int at,double expected){int lo=(int)(Core.RATE/expected*.90),hi=(int)(Core.RATE/expected*1.10),size=4096;double[] corr=new double[hi+2];int best=lo;for(int lag=lo-1;lag<=hi+1;lag++){double xy=0,xx=0,yy=0;for(int i=0;i<size;i++){double x=a[(at+i)*2],y=a[(at+i+lag)*2];xy+=x*y;xx+=x*x;yy+=y*y;}corr[lag]=xy/Math.sqrt(Math.max(1e-20,xx*yy));if(lag>=lo&&lag<=hi&&corr[lag]>corr[best])best=lag;}double l=corr[best-1],m=corr[best],r=corr[best+1],den=l-2*m+r,delta=Math.abs(den)>1e-10?.5*(l-r)/den:0;return Core.RATE/(best+Math.max(-.5,Math.min(.5,delta)));}
 static double cents(double actual,double expected){return 1200*Math.log(actual/expected)/Math.log(2);}
 public static void main(String[] args)throws Exception {
  PitchCorrector.Config hard=new PitchCorrector.Config();hard.retuneMs=0;hard.strength=1;
  double worst=0;for(int midi:new int[]{40,48,55,60,67,72,79})for(int detune:new int[]{-38,34}){double target=440*Math.pow(2,(midi-69)/12.0);float[] src=voice(target,detune,0,Core.RATE*2),out=correct(src,hard);double error=Math.abs(cents(frequency(out,48000,target),target));worst=Math.max(worst,error);System.out.println("Vocal note "+midi+" detune "+detune+" -> "+error+" cents");check(error<14&&error<Math.abs(detune)*.5,"Rich harmonic vocal converges on the correct note: "+midi);boolean stereo=true;double step=0;for(int i=1;i<out.length/2;i++){stereo&=Float.isFinite(out[i*2])&&Math.abs(out[i*2+1]-out[i*2]*.6)<1e-6;step=Math.max(step,Math.abs(out[i*2]-out[(i-1)*2]));}check(stereo&&step<.23,"Stereo phase relationship and no single-sample output spikes");}
  float[] vibrato=voice(440,12,35,Core.RATE*3),locked=correct(vibrato,hard);double maxError=0;for(int at=24000;at<Core.RATE*2.6;at+=9600)maxError=Math.max(maxError,Math.abs(cents(frequency(locked,at,440),440)));System.out.println("Hard vibrato worst error: "+maxError+" cents");check(maxError<24,"Hard retune suppresses vibrato instead of following it out of tune");
  float[] exact=voice(440,0,0,Core.RATE*2),same=correct(exact,hard);double mse=0;for(int i=12000;i<same.length-12000;i++)mse+=Math.pow(exact[i]-same[i],2);mse/=(same.length-24000);check(mse<.00001,"Already-tuned vowels stay transparent");
  float[] phrase=new float[Core.RATE*4*2];float[] first=voice(220,30,0,Core.RATE),last=voice(329.6276,-30,0,Core.RATE);System.arraycopy(first,0,phrase,Core.RATE,first.length);System.arraycopy(last,0,phrase,Core.RATE*5,last.length);Random random=new Random(38);for(int f=Core.RATE*2;f<Core.RATE*2.3;f++)phrase[f*2]=phrase[f*2+1]=(float)(random.nextGaussian()*.025);float[] tuned=correct(phrase,hard);boolean preserved=true;for(int f=Core.RATE*2+4800;f<Core.RATE*2.3-4800;f++)preserved&=tuned[f*2]==phrase[f*2]&&tuned[f*2+1]==phrase[f*2+1];check(preserved,"Unvoiced consonant/noise stays sample-identical away from vowel edges");check(Math.abs(cents(frequency(tuned,48000,220),220))<14&&Math.abs(cents(frequency(tuned,Core.RATE*3,329.6276),329.6276))<14,"Separate vowel runs correct independently");
  PitchCorrector.Config major=new PitchCorrector.Config();major.scale=1;major.retuneMs=0;float[] offScale=correct(voice(369.9944,-12,0,Core.RATE*2),major);check(Math.abs(cents(frequency(offScale,48000,349.2282),349.2282))<18,"Key/scale correction moves F-sharp down to F in C major");
  double minRatio=1;for(int at=4800;at<Core.RATE*3-4800;at+=960){double dry=0,wet=0;for(int i=0;i<960;i++){dry+=vibrato[(at+i)*2]*vibrato[(at+i)*2];wet+=locked[(at+i)*2]*locked[(at+i)*2];}minRatio=Math.min(minRatio,Math.sqrt(wet/Math.max(1e-12,dry)));}System.out.println("Vibrato minimum RMS ratio: "+minRatio);check(minRatio>.45,"Hard retune does not produce deep amplitude dropouts while crossing a note");
  PitchCorrector.Config natural=new PitchCorrector.Config();natural.retuneMs=80;float[] relaxed=correct(vibrato,natural);double naturalError=0;for(int at=24000;at<Core.RATE*2.6;at+=9600)naturalError=Math.max(naturalError,Math.abs(cents(frequency(relaxed,at,440),440)));check(naturalError>maxError*2,"Natural retune preserves more of the singer's vibrato than Hard");
  float[] legato=new float[Core.RATE*3*2];double phase=0;int[] melody={60,64,62};for(int i=0;i<Core.RATE*3;i++){int n=i/Core.RATE;double pitch=melody[n]+.32,fade=(i%Core.RATE)/(double)Core.RATE;if(n>0&&fade<.06)pitch=(melody[n-1]+.32)+(melody[n]-melody[n-1])*fade/.06;phase+=2*Math.PI*440*Math.pow(2,(pitch-69)/12)/Core.RATE;float v=(float)((Math.sin(phase)+.5*Math.sin(phase*2)+.3*Math.sin(phase*3))*.12);legato[i*2]=v;legato[i*2+1]=v;}
  float[] melodyOut=correct(legato,hard);boolean notes=true;for(int n=0;n<3;n++){double hz=440*Math.pow(2,(melody[n]-69)/12.0);notes&=Math.abs(cents(frequency(melodyOut,n*Core.RATE+24000,hz),hz))<14;}check(notes,"Legato note changes settle on each new target rather than staying on the previous note");
  System.out.println(passed+" vocal regression checks passed; worst stable-note error "+worst+" cents.");
 }
}
